// One row per day, newest at the bottom. Every column except Date is treated as a metric.
const rows = $input.all().map((i) => i.json);
if (rows.length < 2) throw new Error('The KPI sheet needs at least two rows of data to compare.');

const toNumber = (v) => (typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')));
const latest = rows[rows.length - 1];
const previous = rows[rows.length - 2];
const week = rows.slice(-8, -1); // the 7 days before the latest one

const metrics = Object.keys(latest)
  .filter((k) => !['date', 'row_number'].includes(k.toLowerCase()))
  .filter((k) => !Number.isNaN(toNumber(latest[k])));

const fmt = (n) => (Number.isFinite(n) ? n.toLocaleString('en-US', { maximumFractionDigits: 2 }) : 'n/a');
const pct = (now, before) => (before ? ((now - before) / Math.abs(before)) * 100 : null);

const table = metrics.map((m) => {
  const now = toNumber(latest[m]);
  const before = toNumber(previous[m]);
  const values = week.map((r) => toNumber(r[m])).filter(Number.isFinite);
  const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : NaN;
  return { metric: m, now, before, vsYesterday: pct(now, before), avg7: avg, vsAverage: pct(now, avg) };
});

const sign = (p) => (p === null || !Number.isFinite(p) ? 'n/a' : (p > 0 ? '+' : '') + p.toFixed(1) + '%');
const summaryForAi = table
  .map((r) => `${r.metric}: ${fmt(r.now)} (yesterday ${fmt(r.before)}, ${sign(r.vsYesterday)}; 7 day average ${fmt(r.avg7)}, ${sign(r.vsAverage)})`)
  .join('\n');

const cell = 'style="padding:6px 10px;border-bottom:1px solid #e5e5e5;text-align:right"';
const tableHtml = `<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px">
<tr><th style="text-align:left;padding:6px 10px">Metric</th><th ${cell}>Latest</th><th ${cell}>Day before</th><th ${cell}>Change</th><th ${cell}>7 day avg</th></tr>
${table.map((r) => `<tr><td style="padding:6px 10px;border-bottom:1px solid #e5e5e5">${r.metric}</td><td ${cell}>${fmt(r.now)}</td><td ${cell}>${fmt(r.before)}</td><td ${cell}>${sign(r.vsYesterday)}</td><td ${cell}>${fmt(r.avg7)}</td></tr>`).join('')}
</table>`;

return [{ json: { date: latest.Date || latest.date || 'latest day', summaryForAi, tableHtml } }];
